async def check_password_policy(password: str, minimum_length: int = 12, forbidden_terms: tuple[str, ...] = ()) -> list[str]:
    if minimum_length < 1:
        raise ValueError("Minimum password length must be positive")
    await asyncio.sleep(0)
    failures = []
    if len(password) < minimum_length:
        failures.append("Password is too short")
    if not any(character.isupper() for character in password):
        failures.append("Password needs an uppercase letter")
    if not any(character.islower() for character in password):
        failures.append("Password needs a lowercase letter")
    if not any(character.isdigit() for character in password):
        failures.append("Password needs a digit")
    if not any(not character.isalnum() and not character.isspace() for character in password):
        failures.append("Password needs a symbol")
    if any(character.isspace() for character in password):
        failures.append("Password cannot contain whitespace")
    if any(term and term.casefold() in password.casefold() for term in forbidden_terms):
        failures.append("Password contains a forbidden term")
    return failures

async def parse_delimited_text(text: str, delimiter: str = ",", strip_fields: bool = True, skip_empty_rows: bool = True) -> list[list[str]]:
    if len(delimiter) != 1 or delimiter in {"\r", "\n", '"'}:
        raise ValueError("Delimiter must be one character other than a newline or quote")
    await asyncio.sleep(0)
    rows: list[list[str]] = []
    stream = io.StringIO(text, newline="")
    reader = csv.reader(stream, delimiter=delimiter, strict=True)
    try:
        for row in reader:
            if skip_empty_rows and not row:
                continue
            if strip_fields:
                row = [field.strip() for field in row]
            rows.append(row)
    except csv.Error as error:
        raise ValueError(f"Invalid delimited text near line {reader.line_num}: {error}") from error
    finally:
        stream.close()
    return rows

async def get_with_backoff(client: Any, url: str, attempts: int = 3, initial_delay: float = 0.5) -> Any:
    if attempts < 1:
        raise ValueError("Attempts must be at least one")
    if not math.isfinite(initial_delay) or initial_delay < 0:
        raise ValueError("Initial delay must be finite and nonnegative")
    delay = initial_delay
    for attempt in range(attempts):
        response = await client.get(url)
        if response.status_code not in {429, 502, 503, 504}:
            response.raise_for_status()
            return response
        if attempt + 1 == attempts:
            raise TimeoutError(f"Retry budget exhausted after HTTP {response.status_code}")
        await asyncio.sleep(delay)
        delay = min(delay * 2, 60.0)
    raise TimeoutError("No request completed")

async def validate_available_username(username: str, client: Any, *, reserved: tuple[str, ...] = ("admin", "support", "root"), timeout: float = 3.0) -> str:
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("Availability timeout must be finite and positive")
    candidate = username.strip().lower()
    if not 3 <= len(candidate) <= 30:
        raise ValueError("Username must contain between 3 and 30 characters")
    if re.fullmatch(r"[a-z][a-z0-9_]*", candidate) is None:
        raise ValueError("Username must start with a letter and use ASCII letters, digits, or underscores")
    if candidate.endswith("_"):
        raise ValueError("Username cannot end with an underscore")
    if "__" in candidate:
        raise ValueError("Username cannot contain consecutive underscores")
    if candidate in {name.strip().lower() for name in reserved}:
        raise ValueError("Username is reserved")
    try:
        available = await asyncio.wait_for(client.is_username_available(candidate), timeout=timeout)
    except TimeoutError as exc:
        raise TimeoutError("Username availability check timed out") from exc
    if not isinstance(available, bool):
        raise TypeError("Availability service must return a boolean")
    if not available:
        raise ValueError("Username is already in use")
    return candidate

async def apply_savings_interest(balance: float, period_rate: float) -> float:
    if not math.isfinite(balance) or balance < 0:
        raise ValueError("Balance must be finite and nonnegative")
    if not math.isfinite(period_rate) or period_rate < -1:
        raise ValueError("Period rate must be finite and at least -1")
    await asyncio.sleep(0)
    return balance * (1 + period_rate)

def validate_record_schema(record: dict[str, object], schema: dict[str, type], *, required: tuple[str, ...] = (), nullable: tuple[str, ...] = (), allow_extra: bool = False) -> dict[str, object]:
    if not isinstance(record, dict) or not isinstance(schema, dict):
        raise TypeError('Record and schema must be dictionaries')
    for field, expected_type in schema.items():
        if not isinstance(field, str) or not field:
            raise ValueError('Schema field names must be nonempty strings')
        if not isinstance(expected_type, type):
            raise TypeError(f'Schema type for {field!r} must be a class')
    for field in required:
        if field not in schema:
            raise ValueError(f'Required field {field!r} is not defined in the schema')
    for field in nullable:
        if field not in schema:
            raise ValueError(f'Nullable field {field!r} is not defined in the schema')
    for field in required:
        if field not in record:
            raise KeyError(f'Missing required field {field!r}')
    validated: dict[str, object] = {}
    for field, value in record.items():
        if not isinstance(field, str):
            raise TypeError('Record field names must be strings')
        if field not in schema:
            if not allow_extra:
                raise ValueError(f'Unexpected field {field!r}')
            validated[field] = value
            continue
        expected_type = schema[field]
        if value is None and field in nullable:
            validated[field] = None
            continue
        if expected_type in (int, float) and isinstance(value, bool):
            raise TypeError(f'Field {field!r} must not be a boolean')
        if not isinstance(value, expected_type):
            raise TypeError(f'Field {field!r} must be an instance of {expected_type.__name__}')
        validated[field] = value
    return validated

def trailing_moving_average(values: list[float | None], window: int, min_periods: int | None = None) -> list[float | None]:
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError("Window must be a positive integer")
    required = window if min_periods is None else min_periods
    if isinstance(required, bool) or not isinstance(required, int) or not 1 <= required <= window:
        raise ValueError("Minimum periods must be an integer between 1 and window")
    numbers = [None if value is None else float(value) for value in values]
    if any(value is not None and not math.isfinite(value) for value in numbers):
        raise ValueError("Nonmissing values must be finite")
    result: list[float | None] = []
    for end in range(len(numbers)):
        start = max(0, end - window + 1)
        observed = [value for value in numbers[start:end + 1] if value is not None]
        if len(observed) < required:
            result.append(None)
        else:
            average = math.fsum(value / len(observed) for value in observed)
            result.append(average)
    return result

def group_products_by_category(products: list[tuple[str, str]]) -> dict[str, list[str]]:
    grouped: dict[str, list[str]] = {}
    for product_id, category in products:
        if category not in grouped:
            grouped[category] = []
        grouped[category].append(product_id)
    return grouped

def forward_fill_records(records: list[dict[str, object]], columns: list[str], *, group_key: str | None = None, max_gap: int | None = None) -> list[dict[str, object]]:
    if max_gap is not None and (isinstance(max_gap, bool) or not isinstance(max_gap, int)):
        raise TypeError("max_gap must be an integer or None")
    if max_gap is not None and max_gap < 0:
        raise ValueError("max_gap must be nonnegative")
    columns = list(dict.fromkeys(columns))
    if group_key is not None and group_key in columns:
        raise ValueError("The grouping column cannot be filled")
    state: dict[object, dict[str, tuple[object, int]]] = {}
    result: list[dict[str, object]] = []
    for record in records:
        row = record.copy()
        group: object = None
        if group_key is not None:
            if group_key not in row:
                raise KeyError(f"Missing grouping column {group_key!r}")
            group = row[group_key]
        try:
            history = state.setdefault(group, {})
        except TypeError:
            raise TypeError("Grouping values must be hashable") from None
        for column in columns:
            value = row.get(column)
            if value is not None:
                history[column] = (value, 0)
            elif column in history:
                previous, gap = history[column]
                gap += 1
                history[column] = (previous, gap)
                if max_gap is None or gap <= max_gap:
                    row[column] = previous
        result.append(row)
    return result

def iqr_outlier_indices(values: list[float], *, multiplier: float = 1.5, side: str = "both") -> list[int]:
    if not math.isfinite(multiplier) or multiplier < 0:
        raise ValueError("IQR multiplier must be finite and nonnegative")
    if side not in {"both", "low", "high"}:
        raise ValueError("Side must be both, low, or high")
    numbers = [float(value) for value in values]
    if not numbers:
        raise ValueError("Outlier detection requires at least one value")
    if not all(math.isfinite(value) for value in numbers):
        raise ValueError("Outlier detection requires finite values")
    ordered = sorted(numbers)
    quartiles: list[float] = []
    for probability in (0.25, 0.75):
        position = (len(ordered) - 1) * probability
        lower = math.floor(position)
        upper = math.ceil(position)
        fraction = position - lower
        quartiles.append(ordered[lower] * (1 - fraction) + ordered[upper] * fraction)
    spread = quartiles[1] - quartiles[0]
    if not math.isfinite(spread):
        raise ValueError("Interquartile range exceeds the floating-point range")
    padding = 0.0 if multiplier == 0 else multiplier * spread
    lower_fence = quartiles[0] - padding
    upper_fence = quartiles[1] + padding
    result: list[int] = []
    for index, value in enumerate(numbers):
        if side in {"both", "low"} and value < lower_fence:
            result.append(index)
        elif side in {"both", "high"} and value > upper_fence:
            result.append(index)
    return result

def next_pagination_url(link_header: str, base_url: str, *, allow_cross_origin: bool = False) -> str | None:
    base = urlsplit(base_url)
    if base.scheme not in {"http", "https"} or not base.hostname:
        raise ValueError("Base URL must be an absolute HTTP or HTTPS URL")
    base_port = base.port if base.port is not None else (443 if base.scheme == "https" else 80)
    base_origin = (base.scheme, base.hostname, base_port)
    for entry in re.split(r',(?=\s*<)', link_header):
        if not entry.strip():
            continue
        match = re.fullmatch(r'\s*<([^>]+)>(.*)', entry)
        if match is None:
            raise ValueError("Malformed pagination Link header entry")
        attributes = match.group(2)
        relation = re.search(r'(?:^|;)\s*rel\s*=\s*(?:"([^"]*)"|([^;\s]+))', attributes, re.IGNORECASE)
        if relation is None:
            continue
        relations = (relation.group(1) or relation.group(2) or "").split()
        if "next" not in relations:
            continue
        resolved = urljoin(base_url, match.group(1))
        target = urlsplit(resolved)
        if target.scheme not in {"http", "https"} or not target.hostname:
            raise ValueError("Pagination link must resolve to an HTTP or HTTPS URL")
        if target.username is not None or target.password is not None:
            raise ValueError("Pagination URL must not contain credentials")
        target_port = target.port if target.port is not None else (443 if target.scheme == "https" else 80)
        target_origin = (target.scheme, target.hostname, target_port)
        if not allow_cross_origin and target_origin != base_origin:
            raise ValueError("Cross-origin pagination link is not permitted")
        return urlunsplit((target.scheme, target.netloc, target.path, target.query, ""))
    return None

def invalidate_cache_keys(cache: dict[str, object], keys: Iterable[str]) -> Iterator[tuple[str, object]]:
    for key in keys:
        if key not in cache:
            continue
        value = cache.pop(key)
        yield key, value

def identifier_batch_errors(names: Iterable[str], maximum_length: int = 64, reserved_names: tuple[str, ...] = ()) -> Iterator[tuple[int, str]]:
    if maximum_length < 1:
        raise ValueError("Maximum identifier length must be positive")
    reserved = set(reserved_names)
    seen: set[str] = set()
    for index, name in enumerate(names):
        if not name:
            yield index, "Identifier must not be empty"
        else:
            if len(name) > maximum_length:
                yield index, f"Identifier exceeds {maximum_length} characters"
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) is None:
                yield index, "Identifier must use ASCII letters, digits, and underscores and cannot start with a digit"
            if name in reserved:
                yield index, "Identifier is reserved"
            if name in seen:
                yield index, "Identifier duplicates an earlier entry"
        seen.add(name)

def iter_header_values(headers: Iterable[tuple[str, str]], name: str) -> Iterator[str]:
    target = name.casefold()
    for header_name, value in headers:
        normalized_name = header_name.casefold()
        if normalized_name == target:
            yield value.strip()

def iter_nonempty_lines(path: str, encoding: str = "utf-8") -> Iterator[str]:
    with open(path, "r", encoding=encoding) as source:
        for line in source:
            text = line.rstrip("\r\n")
            if not text.strip():
                continue
            yield text

def iter_text_matches(text: str, needle: str, overlap: bool = False, whole_word: bool = False) -> Iterator[int]:
    if not needle:
        raise ValueError("The search string must not be empty")
    position = 0
    while position <= len(text) - len(needle):
        found = text.find(needle, position)
        if found < 0:
            break
        end = found + len(needle)
        left_boundary = found == 0 or not (text[found - 1].isalnum() or text[found - 1] == "_")
        right_boundary = end == len(text) or not (text[end].isalnum() or text[end] == "_")
        accepted = not whole_word or (left_boundary and right_boundary)
        if accepted:
            yield found
        position = found + (len(needle) if accepted and not overlap else 1)

def histogram_updates(values: Iterable[float], bin_width: float = 1.0, origin: float = 0.0) -> Iterator[tuple[int, int]]:
    if not math.isfinite(bin_width) or bin_width <= 0:
        raise ValueError('bin_width must be finite and positive')
    if not math.isfinite(origin):
        raise ValueError('origin must be finite')
    counts: dict[int, int] = {}
    for value in values:
        if not math.isfinite(value):
            raise ValueError('histogram values must be finite')
        position = (value - origin) / bin_width
        if not math.isfinite(position):
            raise ValueError('value cannot be represented as a bin position')
        index = math.floor(position)
        counts[index] = counts.get(index, 0) + 1
        yield index, counts[index]

def simulate_dice_race(players: list[str], *, winning_score: int = 20, max_turns: int = 100, seed: int | None = None) -> Iterator[tuple[int, str, int, int, str]]:
    if not players:
        raise ValueError("At least one player is required")
    if any(not isinstance(player, str) or not player for player in players):
        raise ValueError("Player names must be nonempty strings")
    if len(set(players)) != len(players):
        raise ValueError("Player names must be unique")
    if winning_score < 1 or max_turns < 1:
        raise ValueError("Winning score and turn limit must be positive")
    roster = tuple(players)
    scores = dict.fromkeys(roster, 0)
    rng = random.Random(seed)
    for turn in range(1, max_turns + 1):
        player = roster[(turn - 1) % len(roster)]
        roll = rng.randint(1, 6)
        if roll == 1:
            scores[player] = max(0, scores[player] - 2)
            status = "penalty"
        else:
            scores[player] += roll
            status = "advance"
        if scores[player] >= winning_score:
            status = "win"
        elif turn == max_turns:
            status = "turn_limit"
        yield turn, player, roll, scores[player], status
        if status == "win":
            return

def parse_text_properties(self: object, text: str, delimiter: str = ";") -> dict[str, str]:
    if not delimiter:
        raise ValueError("Property delimiter must not be empty")
    properties: dict[str, str] = {}
    for position, segment in enumerate(text.split(delimiter), start=1):
        segment = segment.strip()
        if not segment:
            continue
        key, marker, value = segment.partition("=")
        if not marker:
            raise ValueError(f"Property {position} has no equals sign")
        key = key.strip()
        if not key:
            raise ValueError(f"Property {position} has an empty key")
        if key in properties:
            raise ValueError(f"Duplicate property key: {key}")
        properties[key] = value.strip()
    return properties

def select_pending_jobs(self: object, jobs: list[dict[str, object]], *, limit: int, priority_key: str = "priority") -> list[dict[str, object]]:
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("Job limit must be an integer")
    if limit < 0:
        raise ValueError("Job limit cannot be negative")
    if limit == 0:
        return []
    queue: list[tuple[int | float, int, dict[str, object]]] = []
    for position, job in enumerate(jobs):
        status = job.get("status", "pending")
        if status in ("cancelled", "completed", "running"):
            continue
        if status != "pending":
            raise ValueError("Job status is not recognized")
        if priority_key not in job:
            raise KeyError("Pending job is missing its priority")
        priority = job[priority_key]
        if isinstance(priority, bool) or not isinstance(priority, (int, float)):
            raise TypeError("Job priorities must be integers or floats")
        if isinstance(priority, float) and not math.isfinite(priority):
            raise ValueError("Job priorities must be finite")
        heapq.heappush(queue, (priority, position, job))
    selected: list[dict[str, object]] = []
    while queue and len(selected) < limit:
        priority, position, job = heapq.heappop(queue)
        selected.append(job)
    return selected

def flatten_page_ids(self: object, pages: list[list[str]]) -> list[str]:
    identifiers: list[str] = []
    for page in pages:
        for identifier in page:
            identifiers.append(identifier)
    return identifiers

def propose_rebalance_trades(self: "Portfolio", target_weights: dict[str, Decimal], *, cash: Decimal = Decimal("0"), minimum_trade: Decimal = Decimal("0")) -> dict[str, Decimal]:
    if not cash.is_finite() or cash < 0:
        raise ValueError("Available cash must be finite and nonnegative")
    if not minimum_trade.is_finite() or minimum_trade < 0:
        raise ValueError("Minimum trade must be finite and nonnegative")
    total_weight = Decimal("0")
    for symbol, weight in target_weights.items():
        if not weight.is_finite() or not Decimal("0") <= weight <= Decimal("1"):
            raise ValueError(f"Invalid target weight for {symbol}")
        total_weight += weight
    if total_weight > Decimal("1"):
        raise ValueError("Target weights must not sum to more than one")
    symbols = sorted(set(self.positions) | set(target_weights))
    current_values = {}
    capital = cash
    for symbol in symbols:
        if symbol not in self.prices:
            raise KeyError(f"Missing market price for {symbol}")
        price = self.prices[symbol]
        quantity = self.positions.get(symbol, Decimal("0"))
        if not price.is_finite() or price <= 0:
            raise ValueError(f"Market price must be finite and positive for {symbol}")
        if not quantity.is_finite() or quantity < 0:
            raise ValueError(f"Position must be finite and nonnegative for {symbol}")
        value = quantity * price
        current_values[symbol] = value
        capital += value
    if capital == 0:
        return {}
    trades = {}
    for symbol in symbols:
        target_value = capital * target_weights.get(symbol, Decimal("0"))
        difference = target_value - current_values[symbol]
        rounded = difference.quantize(self.currency_quantum, rounding=ROUND_HALF_UP)
        if rounded != 0 and abs(rounded) >= minimum_trade:
            trades[symbol] = rounded
    return trades

def cell_center(self: "Grid", row: int, column: int, clamp: bool = False) -> tuple[float, float]:
    rows, columns = self.shape
    width, height = self.cell_size
    if rows <= 0 or columns <= 0:
        raise ValueError("Grid dimensions must be positive")
    if not math.isfinite(width) or not math.isfinite(height) or width <= 0 or height <= 0:
        raise ValueError("Cell dimensions must be finite and positive")
    if clamp:
        row = min(max(row, 0), rows - 1)
        column = min(max(column, 0), columns - 1)
    elif not (0 <= row < rows and 0 <= column < columns):
        raise IndexError("Cell index is outside the grid")
    origin_x, origin_y = self.origin
    center_x = origin_x + (column + 0.5) * width
    center_y = origin_y + (row + 0.5) * height
    return center_x, center_y
